import { NavLink, Outlet, useNavigate } from "react-router-dom";

const menuItems = [
  { to: "/dashboard",                 label: "Dashboard",       icon: "⊞", end: true },
  { to: "/dashboard/announcements",   label: "Announcements",   icon: "≡" },
  { to: "/dashboard/find-workers",    label: "Find Workers",    icon: "⌖" },
  { to: "/dashboard/company-profile", label: "Company Profile", icon: "⊙" },
];

const accountItems = [
  { to: "/dashboard/settings", label: "Settings", icon: "⊕" },
];

export default function DashboardLayout() {
  const navigate = useNavigate();

  const navItem = (item) => (
    <NavLink
      key={item.to}
      to={item.to}
      end={item.end}
      className={({ isActive }) =>
        `flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-all
        ${isActive
          ? "bg-red/10 text-red font-medium"
          : "text-gray-500 hover:bg-cream hover:text-gray-900"}`
      }
    >
      <span className="w-4 text-center">{item.icon}</span>
      {item.label}
    </NavLink>
  );

  return (
    <div className="flex min-h-screen bg-cream">
      {/* Sidebar */}
      <aside className="w-60 bg-white border-r border-gray-200 fixed top-0 left-0 bottom-0 flex flex-col px-4 py-5 overflow-y-auto">
        {/* Logo */}
        <div
          className="flex items-center gap-2 px-2 mb-5 cursor-pointer"
          onClick={() => navigate("/")}
        >
          <div className="w-8 h-8 bg-red rounded-lg flex items-center justify-center text-white font-bold text-sm">
            A
          </div>
          <span className="font-semibold text-gray-900">WorkBridge DZ</span>
        </div>

        {/* Menu */}
        <p className="text-[10px] tracking-widest text-gray-300 px-2 mb-1">MENU</p>
        <nav className="flex flex-col gap-1 mb-3">{menuItems.map(navItem)}</nav>

        <div className="h-px bg-gray-100 my-2" />

        <p className="text-[10px] tracking-widest text-gray-300 px-2 mb-1">ACCOUNT</p>
        <nav className="flex flex-col gap-1">{accountItems.map(navItem)}</nav>

        {/* User info */}
        <div className="mt-auto flex items-center gap-2 bg-cream rounded-xl p-3 mb-2">
          <div className="w-9 h-9 bg-red rounded-lg flex items-center justify-center text-white text-xs font-semibold">
            TC
          </div>
          <div>
            <p className="text-sm font-medium text-gray-900">TechCorp Algérie</p>
            <p className="text-xs text-gray-400">Business</p>
          </div>
        </div>

        <button
          onClick={() => navigate("/")}
          className="text-left text-sm text-red px-3 py-2 hover:underline"
        >
          ← Log out
        </button>
      </aside>

      {/* Main */}
      <div className="ml-60 flex-1 flex flex-col min-h-screen">
        <div className="h-13 bg-cream border-b border-gray-200 flex items-center justify-end px-8 py-3">
          <span className="text-sm text-gray-400">Business Portal</span>
        </div>
        <div className="p-8">
          <Outlet />
        </div>
      </div>
    </div>
  );
}
